func eksGoR3(st []lstate, jobs []Job, n uint64) {
	sp, j := (*[3]lstate)(st), (*[3]Job)(jobs)
	sts := *sp // a local copy is addressed off SP, with no base register per lane
	s0 := &sts[0]
	var l0, r0 uint32
	s1 := &sts[1]
	var l1, r1 uint32
	s2 := &sts[2]
	var l2, r2 uint32
	for ; n > 0; n-- {
		for pass := 0; pass < 2; pass++ {
			kp0 := &j[0].Key[pass&1]
			for i := 0; i < 18; i++ {
				s0.P[i] ^= kp0[i]
			}
			l0, r0 = 0, 0
			kp1 := &j[1].Key[pass&1]
			for i := 0; i < 18; i++ {
				s1.P[i] ^= kp1[i]
			}
			l1, r1 = 0, 0
			kp2 := &j[2].Key[pass&1]
			for i := 0; i < 18; i++ {
				s2.P[i] ^= kp2[i]
			}
			l2, r2 = 0, 0
			for i := 0; i < 18; i += 2 {
				l0 ^= s0.P[0]
				l1 ^= s1.P[0]
				l2 ^= s2.P[0]
				for i := 1; i < 17; i += 2 {
					r0 ^= s0.P[i+0]
					r0 ^= ((s0.S[0][l0>>24] + s0.S[1][l0>>16&255]) ^ s0.S[2][l0>>8&255]) + s0.S[3][l0&255]
					r1 ^= s1.P[i+0]
					r1 ^= ((s1.S[0][l1>>24] + s1.S[1][l1>>16&255]) ^ s1.S[2][l1>>8&255]) + s1.S[3][l1&255]
					r2 ^= s2.P[i+0]
					r2 ^= ((s2.S[0][l2>>24] + s2.S[1][l2>>16&255]) ^ s2.S[2][l2>>8&255]) + s2.S[3][l2&255]
					l0 ^= s0.P[i+1]
					l0 ^= ((s0.S[0][r0>>24] + s0.S[1][r0>>16&255]) ^ s0.S[2][r0>>8&255]) + s0.S[3][r0&255]
					l1 ^= s1.P[i+1]
					l1 ^= ((s1.S[0][r1>>24] + s1.S[1][r1>>16&255]) ^ s1.S[2][r1>>8&255]) + s1.S[3][r1&255]
					l2 ^= s2.P[i+1]
					l2 ^= ((s2.S[0][r2>>24] + s2.S[1][r2>>16&255]) ^ s2.S[2][r2>>8&255]) + s2.S[3][r2&255]
				}
				l0, r0 = r0^s0.P[17], l0
				l1, r1 = r1^s1.P[17], l1
				l2, r2 = r2^s2.P[17], l2
				s0.P[i], s0.P[i+1] = l0, r0
				s1.P[i], s1.P[i+1] = l1, r1
				s2.P[i], s2.P[i+1] = l2, r2
			}
			for b := 0; b < 4; b++ {
				for i := 0; i < 256; i += 2 {
					l0 ^= s0.P[0]
					l1 ^= s1.P[0]
					l2 ^= s2.P[0]
					for i := 1; i < 17; i += 2 {
						r0 ^= s0.P[i+0]
						r0 ^= ((s0.S[0][l0>>24] + s0.S[1][l0>>16&255]) ^ s0.S[2][l0>>8&255]) + s0.S[3][l0&255]
						r1 ^= s1.P[i+0]
						r1 ^= ((s1.S[0][l1>>24] + s1.S[1][l1>>16&255]) ^ s1.S[2][l1>>8&255]) + s1.S[3][l1&255]
						r2 ^= s2.P[i+0]
						r2 ^= ((s2.S[0][l2>>24] + s2.S[1][l2>>16&255]) ^ s2.S[2][l2>>8&255]) + s2.S[3][l2&255]
						l0 ^= s0.P[i+1]
						l0 ^= ((s0.S[0][r0>>24] + s0.S[1][r0>>16&255]) ^ s0.S[2][r0>>8&255]) + s0.S[3][r0&255]
						l1 ^= s1.P[i+1]
						l1 ^= ((s1.S[0][r1>>24] + s1.S[1][r1>>16&255]) ^ s1.S[2][r1>>8&255]) + s1.S[3][r1&255]
						l2 ^= s2.P[i+1]
						l2 ^= ((s2.S[0][r2>>24] + s2.S[1][r2>>16&255]) ^ s2.S[2][r2>>8&255]) + s2.S[3][r2&255]
					}
					l0, r0 = r0^s0.P[17], l0
					l1, r1 = r1^s1.P[17], l1
					l2, r2 = r2^s2.P[17], l2
					s0.S[b&3][i&255], s0.S[b&3][(i+1)&255] = l0, r0
					s1.S[b&3][i&255], s1.S[b&3][(i+1)&255] = l1, r1
					s2.S[b&3][i&255], s2.S[b&3][(i+1)&255] = l2, r2
				}
			}
		}
	}
	*sp = sts
}

